-- NEXUS OS: loads every default Hyprland setting, then the theme colours.
-- Do not edit this file (an update replaces it). Put your own changes in
-- ~/.config/hypr/hyprland.lua instead.

local dir = "/usr/share/nexus/default/hypr/"
local strict = os.getenv("NEXUS_STRICT") == "1"
local problems = {}

local function load(path)
    if strict then
        dofile(path)
        return
    end
    local ok, err = pcall(dofile, path)
    if not ok then
        problems[#problems + 1] = tostring(err)
        print("NEXUS: problem in " .. path .. ": " .. tostring(err))
    end
end

-- Shortcuts first, so the keyboard still works if a later file has a problem.
for _, name in ipairs({ "bindings", "input", "looknfeel", "rules", "autostart" }) do
    load(dir .. name .. ".lua")
end

local theme = (os.getenv("HOME") or "") .. "/.config/nexus/current/hyprland.lua"
local handle = io.open(theme, "r")
if handle then
    handle:close()
    load(theme)
end

if #problems > 0 then
    hl.on("hyprland.start", function()
        hl.exec_cmd("notify-send -u critical 'NEXUS settings problem' 'Open a terminal (Super + Return) and run: hyprctl configerrors'")
    end)
end
